from pathlib import Path
import tempfile,os,subprocess,hashlib,json
r=Path.cwd();w=r/'.local/controle-2026-10-31';werk=Path(tempfile.mkdtemp(prefix='office-vendor-eol-',dir='/tmp'));index=werk/'index';e=os.environ.copy();e['GIT_INDEX_FILE']=str(index)
run=lambda a,**k:subprocess.run(['git',*a],env=e,check=True,**k)
run(['read-tree','HEAD']);nieuw=sorted(p.relative_to(r).as_posix() for p in (r/'native/vendor/softbuffer').rglob('*') if p.is_file());run(['add','-f','--',*nieuw])
namen=sorted(subprocess.check_output(['git','ls-files','-z','--','native/vendor/iced-runtime','native/vendor/softbuffer'],env=e).decode().rstrip('\0').split('\0'));assert len(namen)==50
h=lambda b:hashlib.sha256(b).hexdigest();verwacht={n:subprocess.check_output(['git','show',':'+n],env=e) for n in namen};oud=(r/'.gitattributes').read_bytes();(w/'native-alpha41-attributen-voor').write_bytes(oud)
def checkout(naam):
 p=werk/naam;p.mkdir();run(['-c','core.autocrlf=true','checkout-index','--prefix='+str(p)+'/', '-f','--',*namen]);return {n:{'git_sha256':h(verwacht[n]),'checkout_sha256':h((p/n).read_bytes()),'git_bytes':len(verwacht[n]),'checkout_bytes':(p/n).stat().st_size,'bytegelijk':verwacht[n]==(p/n).read_bytes()} for n in namen}
voor=checkout('voor');assert any(not v['bytegelijk'] for n,v in voor.items() if '/iced-runtime/' in n);assert any(not v['bytegelijk'] for n,v in voor.items() if '/softbuffer/' in n)
extra=b'\n# Ook deze vastgepinde bronnen blijven op Windows exact gelijk aan de Git-bytes.\nnative/vendor/iced-runtime/** -text -whitespace\nnative/vendor/softbuffer/** -text -whitespace\n';assert b'native/vendor/iced-runtime/**' not in oud and b'native/vendor/softbuffer/**' not in oud;(r/'.gitattributes').write_bytes(oud+extra);run(['add','--','.gitattributes']);na=checkout('na');assert all(v['bytegelijk'] for v in na.values())
rapport={'omvang':'Geïsoleerde tijdelijke index met core.autocrlf=true; de echte index blijft ongewijzigd. Runtimebron uit de afgesloten alpha40-Git-bron, plus de nieuwe softbufferbron. Alleen twee aanvullende, gerichte vendorregels; geen bestaande bronhash, logregel, masker of tolerantie gewijzigd.','basiscommit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'werkmap':str(werk),'bestanden':len(namen),'voor_afwijkingen':sum(not v['bytegelijk'] for v in voor.values()),'na_afwijkingen':sum(not v['bytegelijk'] for v in na.values()),'oude_attributen_sha256':h(oud),'nieuwe_attributen_sha256':h(oud+extra),'voor':voor,'na':na};(w/'native-alpha41-vendor-checkout.json').write_text(json.dumps(rapport,ensure_ascii=False,indent=2)+'\n');assert not subprocess.check_output(['git','diff','--cached','--name-only']);print({'bestanden':len(namen),'voor_afwijkingen':rapport['voor_afwijkingen'],'na_afwijkingen':rapport['na_afwijkingen']})
